;========Variáveis do Jogo==========

fase: var #1
tamanho_seq: var #1
indice: var #1
semente: var #1
resposta_certa: var #1
; Cada valor da sequencia representa uma cor:
; 1 = verde
; 2 = vermelho
; 3 = azul
; 4 = amarelo

sequencia: var #17 ;vão existir 15 fases


;--------------Inicio Programa Main------
main:
    loadn r0, #1
    store fase, r0

    loadn r1, #4
    store semente, r1

    call print_TelaInicial

aperta_space:
    inchar r1
    loadn r2, #' '
    cmp r1, r2
    jne aperta_space

roda_fase:
    call ApagaTela

    ; Gera a sequencia
    call gerar_sequencia

    ; Mostra as cores geradas
    call mostrar_sequencia

    ; Espera o jogador digitar
    call receber_resposta

    ; Informa se acertou ou errou
    call verificar_resposta


nova_fase:
	load r0, fase
    inc r0
    store fase, r0 ;indo para a próxima fase
    
    loadn r7, #16 
    cmp r7, r0 ;ve se ja foram as 15 fases
    jne roda_fase
 
 call sair	
	
;---------------Subrotinas---------------


receber_resposta:
    push r0
    push r1
    push r2
    push r3
    push r4

    loadn r0, #0       ; indice
    loadn r4, #1       ; inicialmente considera correto

receber_loop:

    ; Verifica se recebeu todas as cores
    load r1, tamanho_seq
    cmp r0, r1
    jeq fim_resposta

    ; Espera uma tecla
    inchar r2

    ; Tecla 1 = Verde
    loadn r1, #'1'
    cmp r2, r1
    jeq entrada_verde

    ; Tecla 2 = Vermelho
    loadn r1, #'2'
    cmp r2, r1
    jeq entrada_vermelho

    ; Tecla 3 = Azul
    loadn r1, #'3'
    cmp r2, r1
    jeq entrada_azul

    ; Tecla 4 = Amarelo
    loadn r1, #'4'
    cmp r2, r1
    jeq entrada_amarelo

    ; Ignora teclas invalidas
    jmp receber_loop


entrada_verde:
    loadn r3, #1
    call printVerde
    jmp comparar_entrada

entrada_vermelho:
    loadn r3, #2
    call printVermelho
    jmp comparar_entrada

entrada_azul:
    loadn r3, #3
    call printAzul
    jmp comparar_entrada

entrada_amarelo:
    loadn r3, #4
    call printAmarelo
    jmp comparar_entrada


comparar_entrada:

    ; Busca a cor esperada no vetor
    loadn r1, #sequencia
    add r1, r1, r0
    loadi r2, r1

    ; Compara com a cor digitada
    cmp r2, r3
    jne resposta_errada

    jmp continuar_resposta

resposta_errada:
    loadn r4, #0

continuar_resposta:

    ; Pequena pausa para visualizar a cor
    call delay
    call printNeutro
    call delay

    ; Proxima posicao
    inc r0
    jmp receber_loop


fim_resposta:
    store resposta_certa, r4

    pop r4
    pop r3
    pop r2
    pop r1
    pop r0

    rts
	
verificar_resposta:
    push r0
    push r1

    load r0, resposta_certa
    loadn r1, #1
    cmp r0, r1
    jeq resultado_acerto

    jmp resultado_erro


resultado_acerto:
    ;tela de acerto
	call printtrue1Screen
	call delay 
	call printtrue2Screen
	call delay
	call printtrue3Screen
	call delay
	call printtrue4Screen
	call delay
	call printtrue5Screen

	push r2
	push r3
	push r4

    le_resposta1:
		loadn r3, #13
		loadn r4, #115

		inchar r2
		cmp r2, r3
			jeq fim_verificacao

		cmp r2, r4
			jeq sair
			jne maiusculo1

		maiusculo1:
			loadn r4, #83
			cmp r2, r4
				jeq sair
				jne le_resposta1

resultado_erro:
    ; tela de erro
	call printfalseScreen

	push r2
	push r3
	
	le_resposta2:
		loadn r3, #115
		inchar r2

		cmp r2, r3
			jeq sair
			jne maiusculo2

		maiusculo2:
			loadn r3, #83
			cmp r2, r3
				jeq sair
				jne le_resposta2

sair:
  push r1
  push r2
  push r3
  push r4
  push r6
  push r7

  loadn r3, #10
  loadn r6, #13

  div r1, r5, r3
  mod r2, r5, r3

  loadn r3, #'0'

  add r1, r1, r3
  add r2, r2, r3

  loadn r3, #540
  loadn r7, #541

  call printpontuacaoScreen
  outchar r1, r3
  outchar r2, r7

  le_resposta3:

    inchar r4
    cmp r4, r6
      jne le_resposta3
    
    pop r7
    pop r6
    pop r4
    pop r3
    pop r2
    pop r1
    halt

fim_verificacao:
	pop r4
	pop r3
	pop r2
	pop r1
    pop r0
    rts

gerar_sequencia:
	;Calculo do tamanho da sequencia -> tamanho = fase + 2
	
	load r0, fase
	loadn r1, #2
	add r0, r0, r1
	store tamanho_seq, r0
	
	;Define indice como 0
	loadn r0, #0
	store indice, r0
	
	push r0
    push r1 
    push r2
    push r3

gerar_loop:
    ; Verifica se ja gerou todos os valores
    load r0, indice
    load r1, tamanho_seq
    cmp r0, r1
    jeq fim_geracao

    ; X = (109 * semente + 89) mod 256
    load r0, semente
    loadn r1, #109
    mul r0, r0, r1 ;r0 *= 109
    loadn r1, #89
    add r0, r0, r1
    loadn r1, #256
    mod r0, r0, r1
    store semente, r0

    loadn r1, #64
    div r1, r0, r1 ; Converte o resultado para 0, 1, 2 ou 3
    inc r1 ; Add 1 no resultado para virar 1, 2, 3 ou 4

    
    loadn r2, #sequencia
    load r3, indice
    add r2, r2, r3 ; Somando ao endereço inicial do vetor o indice
    storei r2, r1 ; Guarda o valor na posicao indice do vetor sequencia

    ; Avanca para a proxima posicao
    inc r3
    store indice, r3

    jmp gerar_loop

fim_geracao:
    pop r3
    pop r2
    pop r1
    pop r0
rts ;nesse ponto, a sequencia ja ta salva na variavel


mostrar_sequencia:
    push r0
    push r1
    push r2
    push r3

    ; Comeca pelo indice zero
    loadn r0, #0


mostrar_loop:

    ; Verifica se ja exibiu toda a sequencia
    load r1, tamanho_seq
    cmp r0, r1
    jeq fim_mostrar

    ; Busca o valor da cor no vetor
    loadn r2, #sequencia
    add r2, r2, r0
    loadi r3, r2

    ; Verifica qual cor deve aparecer
    loadn r1, #1
    cmp r3, r1
    jeq mostrar_verde

    loadn r1, #2
    cmp r3, r1
    jeq mostrar_vermelho

    loadn r1, #3
    cmp r3, r1
    jeq mostrar_azul

    loadn r1, #4
    cmp r3, r1
    jeq mostrar_amarelo

    jmp proxima_cor

mostrar_verde:
    call printVerde
    jmp pausa_cor

mostrar_vermelho:
    call printVermelho
    jmp pausa_cor

mostrar_azul:
    call printAzul
    jmp pausa_cor

mostrar_amarelo:
    call printAmarelo
    jmp pausa_cor

; Espera e volta para tela neutra
pausa_cor:
    call delay
    call printNeutro
    call delay

proxima_cor:
    inc r0
    jmp mostrar_loop

fim_mostrar:
    pop r3
    pop r2
    pop r1
    pop r0
    rts

delay:
	push r0
	push r1
	
	loadn r0, #400
	
delay_loop2:
	loadn r1, #1000

delay_loop1:
	dec r1
	jnz delay_loop1
	dec r0
	jnz delay_loop2
	
	pop r1
	pop r0
rts

;================Print Telas================

print_TelaInicial:
  push R0
  push R1
  push R2
  push R3

  loadn R0, #inicial_start
  loadn R1, #0
  loadn R2, #1200

  printinicial_startScreenLoop:

    add R3,R0,R1
    loadi R3, R3
    outchar R3, R1
    inc R1
    cmp R1, R2

    jne printinicial_startScreenLoop

  pop R3
  pop R2
  pop R1
  pop R0
  rts


